INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "やったね、ぷうきち！\nこれならお兄ちゃんたちの\nお手本になれたよね！", 2, 102301, 401, "アヤネ", 24001, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "私たちの勝ちだね！\nぷうきちと一緒なら\nどんなボールでも\nホームランを打ってみせるよ！", 1, 102301, 402, "アヤネ", 24002, "2030/12/17 14:59:59", 2.21, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "やったやったぁ！\nお兄ちゃん、見ててくれた？\n私、すっごくがんばったよ！", 2, 102301, 403, "アヤネ", 24003, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "特訓の成果が出たみたいだ！\nもっと練習を重ねて\nこの調子で上達していこう！", 2, 192201, 701, "アサヒ", 24004, "2030/12/17 14:59:59", 1.99, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "よし、いい感じだ！\nキャプテンとしての仕事は\nきっちり果たせそうだよ", 1, 192201, 702, "アサヒ", 24005, "2030/12/17 14:59:59", 2.21, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "試合に向けて\nいい感覚を掴めた気がするよ！\nこのまま一気に全国大会だ！", 2, 192201, 703, "アサヒ", 24006, "2030/12/17 14:59:59", 3.33, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "このくらい余裕だ\nオレたちは全国大会を\n目指してるんだからな", 2, 192301, 801, "部員３", 24007, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "オレだって\nビーチベースボール選手だ\nどんな球だろうが\n全部スタンドまで飛ばしてやる", 1, 192301, 802, "部員３", 24008, "2030/12/17 14:59:59", 2.68, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい感じだ\nこれなら試合でも活躍できそうだ\n大暴れしてやる！", 2, 192301, 803, "部員３", 24009, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "やった！", 1, 192501, 501, "", 24010, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "勝ったよ！", 1, 192501, 502, "", 24011, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい調子！", 1, 192501, 503, "", 24012, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "あら～…もしかして\n勝っちゃったのかしら？\nみんなの練習を見ていたから\nかもしれないわね", 6, 113501, 111, "ミサト", 24013, "2030/12/17 14:59:59", 5.33, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "みんなの力になりたくて\n先生も頑張ってみました～！\nうまく投げられたみたいで\nよかったわ～！", 1, 113501, 112, "ミサト", 24014, "2030/12/17 14:59:59", 6.85, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "練習お疲れさま～！\n先生も協力できて\nとってもうれしいわ～♪\n次も頑張りましょうね～！", 1, 113501, 113, "ミサト", 24015, "2030/12/17 14:59:59", 3.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "まだ練習が足りねえみてえだな\nこれっぽっちも本気で\n投げてねえっつーの\nもう一回やんぞ！", 1, 192401, 611, "ダイチ", 24016, "2030/12/17 14:59:59", 6.11, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "ふん、当然の結果だな\n俺の球は、誰にも打てねえよ！\nまたやりてえっつーなら\nとことん付き合ってやるぜ！", 1, 192401, 612, "ダイチ", 24017, "2030/12/17 14:59:59", 6.75, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "おっしゃあ！\nこの勢いで全国に行ってやるぜ！\n全員三振で仕留めてやる！", 2, 192401, 613, "ダイチ", 24018, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "きらーん☆\nハツネちゃんの大勝利なのだ～！\nみんながもっと上達できるように\n私もまだまだ頑張るからね！", 2, 113401, 211, "ハツネ", 24019, "2030/12/17 14:59:59", 4.52, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "やったあ！　私の勝ちだね！\nチアリーダーもピッチャーも\nハツネちゃんに任せてよ！", 2, 113401, 212, "ハツネ", 24020, "2030/12/17 14:59:59", 3.89, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "よお～し、この調子でもっと\n頑張ろう…と思ったけど\n超能力を使ったから…\n眠くなってきちゃった…すやぁ…", 1, 113401, 213, "ハツネ", 24021, "2030/12/17 14:59:59", 13.49, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい勝負だったぜ！\nたぎっちまって\nつい本気で投げちまったよ", 1, 106501, 311, "カヤ", 24022, "2030/12/17 14:59:59", 3.17, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "どうだ？\nオレ様のボールは熱かっただろ！\nま、でもおまえらの根性も\nなかなかのもんだったぜ", 1, 106501, 312, "カヤ", 24023, "2030/12/17 14:59:59", 4.42, 24, 0.0, 0.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "なんだよ、そんなもんか？\nこっちはまだまだ投げたりねえ\nもっと勝負しようぜ！", 6, 106501, 313, "カヤ", 24024, "2030/12/17 14:59:59", 2.89, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "あとちょっとだったのに～！\n次こそぷうきちと一緒に\n勝ってみせるからね！", 4, 102301, 421, "アヤネ", 24025, "2030/12/17 14:59:59", 3.71, 24, 0.0, 0.0, 3, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい勝負だったね！\nでも、やっぱり悔しいな…\nもっと練習して\n今度は絶対に俺が勝つから！", 2, 192201, 721, "アサヒ", 24026, "2030/12/17 14:59:59", 5.1, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "ちっ…あと一歩足りなかったか\n次こそは絶対に勝つから\nそのつもりでいろ", 1, 192301, 821, "部員３", 24027, "2030/12/17 14:59:59", 4.34, 24, 0.0, 0.0, 3, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい勝負だったよ\nまたやろうね", 1, 192501, 521, "", 24028, "2030/12/17 14:59:59", 0.0, 24, 0.0, 0.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "とってもよくできました～♪\n頑張ってくれて先生うれしいわ\nこれからも試合に向けて\n練習していきましょうね～", 1, 113501, 101, "ミサト", 24029, "2030/12/17 14:59:59", 5.62, 24, 0.0, -360.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "頑張った成果ね～！\nこのまま練習を続ければ\nもっとすごい成績を残せそうよ\n期待してますからね～！", 1, 113501, 102, "ミサト", 24030, "2030/12/17 14:59:59", 9.58, 24, 0.0, -360.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "いい子、いい子～♪\n頑張り屋さんのあなたを\nたっくさん褒めてあげますからね", 2, 113501, 103, "ミサト", 24031, "2030/12/17 14:59:59", 0.0, 24, 0.0, -360.0, 2, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "夢に向けて、一歩前進できたわね\nこの調子で、夢を叶えましょう\n目指せ、全国大会～！", 2, 113501, 104, "ミサト", 24032, "2030/12/17 14:59:59", 9.13, 24, 0.0, -360.0, 1, 10046);
INSERT INTO `v1_b88f16cd996b3d0df33d03fb770244e49ea89c5390340c706d7a9cb65e4d1621` VALUES ("2020/07/31 12:00:00", "絶好調ね～♪\nきっと試合でも大活躍\n間違いなしだわ\n楽しみにしていますからね～！", 1, 113501, 105, "ミサト", 24033, "2030/12/17 14:59:59", 8.27, 24, 0.0, -360.0, 2, 10046);
